# Identify the 10 evaluable (gray) rows from Supplementary Data 2
sd2_rows = get_rows('41467_2021_22676_MOESM5_ESM.xlsx', 'Sheet1')
gray_row_indices = [i for i, row in enumerate(sd2_rows) if len(row) > 0 and str(row[0]) in ['LC96', 'LC132', 'CRC1', 'LC131', 'LC133', 'LC134', 'LC101', 'LC127', 'LC97', 'LC130']]
evaluable_rows = [sd2_rows[i] for i in gray_row_indices]
print(f"Found {len(evaluable_rows)} evaluable rows: {[r[0] for r in evaluable_rows]}")

# Map clinical response to binary (1=response, 0=no response)
clinical_map = {'PR': 1, 'CR': 1, 'non-PD': 1, 'PD': 0, 'SD': 0}
# Map assay sensitivity: for each patient, get the IC50 of the matched clinical drug, < Cmax = sensitive (1)
drug_cmax = {'PC': 5, 'GC': 10, 'Gef': 0.5, 'Afa': 0.3, 'Osi': 0.2, 'Cri': 0.2, 'Oxi': 5, 'Pem': 1}

records = []
for row in evaluable_rows:
    patient_id = str(row[0]).strip()
    clinical_treatment = str(row[5]).strip()
    # Extract clinical response (column I, index 8)
    clinical_resp = str(row[8]).strip().split(' ')[0]
    truth = {'ref': cell_ref('41467_2021_22676_MOESM5_ESM.xlsx', 'Sheet1', gray_row_indices[evaluable_rows.index(row)] + 1, 9), 'map': clinical_map}

    # Get assay IC50 for the matched drug from Source Data 9
    drug_resp_rows = get_rows('41467_2021_22676_MOESM9_ESM.xlsx', 'Drug responses of LCOs')
    # Find IC50 for patient_id + clinical_treatment
    ic50 = None
    for dr_row in drug_resp_rows:
        if len(dr_row) > 0 and patient_id in str(dr_row[0]):
            ic50 = float(dr_row[1])
            break
    if not ic50:
        # Use viability at Cmax to call sensitivity (viability < 0.5 = sensitive)
        cmax = drug_cmax.get(clinical_treatment.split('+')[0], 1)
        # Find concentration closest to Cmax
        conc_col = 0
        viab_col = None
        for i, val in enumerate(drug_resp_rows[1]):
            if patient_id + '-O' in str(val):
                viab_col = i
                break
        if viab_col:
            for r in range(2, 12):
                conc = float(drug_resp_rows[r][conc_col])
                if abs(conc - cmax) < 1e-3:
                    viab = float(drug_resp_rows[r][viab_col])
                    score = {'ref': cell_ref('41467_2021_22676_MOESM9_ESM.xlsx', 'Drug responses of LCOs', r+1, viab_col+1), 'threshold': 0.5, 'op': '<'}
                    break
    else:
        score = {'ref': cell_ref('41467_2021_22676_MOESM9_ESM.xlsx', 'Drug responses of LCOs', dr_row_idx+1, 2), 'threshold': drug_cmax.get(clinical_treatment.split('+')[0], 1), 'op': '<'}

    records.append({'id': patient_id, 'score': score, 'truth': truth})

CONTRACT = {
    'status': 'computed',
    'fields': {
        'unit': {'value': 'patient', 'evidence': ['article:p27'], 'explanation': 'Each unit is a patient with evaluable clinical response and matched organoid drug assay'},
        'platform': {'value': 'organoid', 'evidence': ['article:p1', 'article:p27'], 'explanation': 'Assay uses patient-derived lung cancer organoids on InSMAR-chip'},
        'readout': {'value': 'viability', 'evidence': ['article:p16'], 'explanation': 'Drug sensitivity measured via alamarBlue viability assay, reported as IC50 or relative viability'},
        'direction': {'value': 'lower_sensitive', 'evidence': ['article:p20'], 'explanation': 'Lower IC50/viability indicates higher sensitivity to treatment'},
        'threshold_rule': {'value': 'fixed_numeric', 'evidence': ['article:p20'], 'explanation': 'Sensitivity threshold based on clinically relevant Cmax concentrations'},
        'threshold_timing': {'value': 'independent_reference', 'evidence': ['article:p20'], 'explanation': 'Cmax thresholds are established clinical values, not optimized on this cohort'},
        'patient_mapping': {'value': 'individual_available', 'evidence': ['article:p27', '41467_2021_22676_MOESM5_ESM.xlsx/Sheet1'], 'explanation': 'Each organoid line is uniquely matched to one patient'},
        'regimen_match': {'value': 'matched', 'evidence': ['article:p27'], 'explanation': 'Drugs tested in the organoid assay match the clinical treatment received by the patient'},
        'n_units': {'value': 10, 'evidence': ['article:p27'], 'explanation': '10 evaluable patients as stated in the article text'},
        'split': {'value': 'same_cohort', 'evidence': ['article:p27'], 'explanation': 'All patients are part of the same prospective study cohort'}
    },
    'headline': {
        'metric': 'accuracy',
        'reported': 1.0,
        'reported_evidence': ['article:p27', 'article:p28'],
        'threshold': None,
        'op': None,
        'score_direction': 'higher',
        'records': records,
        'blocked_reason': None
    },
    'notes': ['100% accuracy (1.0) is reported for 10 evaluable patients where organoid assay results perfectly matched clinical outcomes. Sensitivity calls are based on IC50 < clinical Cmax or viability < 50% at Cmax.']
}

print(f"Contract built with {len(records)} records, accuracy = {CONTRACT['headline']['reported']}")
